CREATE COLUMN TABLE "TEST_AP"."APFS" ("AbsEntry" INTEGER CS_INT NOT NULL , "TableName" NVARCHAR(20) NOT NULL , "FieldName" NVARCHAR(50) NOT NULL , "RefObjType" NVARCHAR(20), "Category" NVARCHAR(1) DEFAULT 'N' NOT NULL , "OrigType" NVARCHAR(1) DEFAULT 'U', "UserSign" SMALLINT CS_INT, "UserSign2" SMALLINT CS_INT, "CreateDate" LONGDATE CS_LONGDATE, "CreateTS" INTEGER CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "UpdateTS" INTEGER CS_INT, "LogInstanc" INTEGER CS_INT DEFAULT 0 NOT NULL , "Type" NVARCHAR(1) DEFAULT 'N', "Descr" NVARCHAR(254), "MaxType" NVARCHAR(1) DEFAULT 'U', PRIMARY KEY ("AbsEntry", "LogInstanc")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "APFS_SECONDARY" ON "TEST_AP"."APFS" ( "TableName" ASC, "FieldName" ASC, "Category" ASC, "LogInstanc" ASC )